public class CineScreen {private int seatsTotal,seatsAvailable;CineScreen(int n){if(n<=0)throw new IllegalArgumentException();seatsTotal=seatsAvailable=n;}void bookSeat(){if(seatsAvailable>0)seatsAvailable--;}void cancelBooking(){if(seatsAvailable<seatsTotal)seatsAvailable++;}int getSeatsAvailable(){return seatsAvailable;}public static void main(String[]a){CineScreen c=new CineScreen(2);c.bookSeat();System.out.println(c.getSeatsAvailable());}}
